normal.css_verbatim:
.option {
  display: block;
  width: 100%;
  text-align: left;
  background: var(--white08);
  border: 1px solid var(--white15);
  border-radius: var(--radius-sm);
  padding: 1.125rem 1.25rem;
  margin-bottom: 0.625rem;
  font-size: 14px;
  line-height: 1.7;
  color: var(--white70);
  cursor: pointer;
  transition: all 0.2s ease;
  font-family: 'DM Sans', sans-serif;
}

hover.css_verbatim:
.option:hover {
  background: rgba(244,120,90,0.1);
  border-color: rgba(244,120,90,0.4);
  color: var(--white);
  transform: translateX(4px);
}

selected.css_verbatim:
.option.selected {
  background: rgba(244,120,90,0.15);
  border-color: var(--coral);
  color: var(--white);
}

container.css_verbatim:
.score-card {
  background: var(--white08);
  border: 1px solid var(--white15);
  border-radius: var(--radius-sm);
  padding: 1rem 1.125rem;
}

label.css_verbatim:
.score-card-label {
  font-size: 11px;
  color: var(--white40);
  margin-bottom: 0.625rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

normal.css_verbatim:
.btn-submit {
  width: 100%;
  padding: 1.125rem;
  border-radius: 50px;
  border: none;
  background: linear-gradient(135deg, var(--coral), #f0704a);
  color: var(--white);
  font-size: 16px;
  font-weight: 600;
  font-family: 'Syne', sans-serif;
  cursor: pointer;
  margin-top: 1rem;
  transition: all 0.2s ease;
  letter-spacing: 0.02em;
}

.btn-cta {
  display: inline-block;
  padding: 0.875rem 2rem;
  border-radius: 50px;
  border: none;
  background: linear-gradient(135deg, var(--coral), #f0704a);
  color: var(--white);
  font-size: 15px;
  font-weight: 600;
  font-family: 'Syne', sans-serif;
  cursor: pointer;
  text-decoration: none;
  transition: all 0.2s ease;
  letter-spacing: 0.02em;
}

.btn-download {
  display: block;
  width: 100%;
  padding: 0.875rem;
  border-radius: 50px;
  border: 1px solid rgba(244,120,90,0.4);
  background: transparent;
  color: var(--coral);
  font-size: 14px;
  font-family: 'DM Sans', sans-serif;
  cursor: pointer;
  margin-top: 1rem;
  transition: all 0.2s ease;
}

.btn-retry {
  display: block;
  width: 100%;
  padding: 0.875rem;
  border-radius: 50px;
  border: 1px solid var(--white15);
  background: transparent;
  color: var(--white40);
  font-size: 14px;
  font-family: 'DM Sans', sans-serif;
  cursor: pointer;
  margin-top: 1rem;
  transition: all 0.2s ease;
}

wrap.css_verbatim:
.progress-wrap {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 2.5rem;
}

track.css_verbatim:
.progress-track {
  flex: 1;
  height: 3px;
  background: var(--white15);
  border-radius: 2px;
  overflow: hidden;
}

fill.css_verbatim:
.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--coral), var(--gold));
  border-radius: 2px;
  transition: width 0.4s ease;
  width: 0%;
}

label.css_verbatim:
.progress-label {
  font-size: 12px;
  color: var(--white40);
  white-space: nowrap;
  min-width: 60px;
  text-align: right;
}

container.css_verbatim:
.profile-card {
  background: var(--card-gradient);
