top_left_coral.css_verbatim:
body::before {
  content: '';
  position: fixed;
  top: -30%;
  left: -20%;
  width: 70%;
  height: 70%;
  background: radial-gradient(ellipse, rgba(244,120,90,0.12) 0%, transparent 70%);
  pointer-events: none;
  z-index: 0;
}

bottom_right_purple.css_verbatim:
body::after {
  content: '';
  position: fixed;
  bottom: -20%;
  right: -20%;
  width: 60%;
  height: 60%;
  background: radial-gradient(ellipse, rgba(100,80,200,0.1) 0%, transparent 70%);
  pointer-events: none;
  z-index: 0;
}
